"use client";
/* Gecko, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Gecko(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("gecko"); }, []);
  return React.createElement("piix-pal", { "pal": "gecko", ...piixAttrs(props) });
}

export default Gecko;
